  const controller = createSearch(q => q === 'a' ? new Promise(r => resolveA = r) : Promise.resolve(['ab']));
  const first = controller.search('a');
  await controller.search('ab');
  resolveA(['a']); await first;
  expect(controller.state.items).toEqual(['ab']);
});

