from app.normalize import normalize

def import_contacts(rows):
    seen = set()
    saved = []
    for row in rows:
        contact = normalize(row)
        if not contact or contact['email'] in seen:
            continue
        seen.add(contact['email'])
        saved.append(contact)
    return {'saved': saved}

